import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷一·39","description":"易小帖 - 卷一·39","frontmatter":{"title":"卷一·39","description":"易小帖 - 卷一·39"},"headers":[],"relativePath":"zh/classics/yixiaotie/039.md","filePath":"zh/classics/yixiaotie/039.md"}'),o={name:"zh/classics/yixiaotie/039.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷一·39",tabindex:"-1"},[r("卷一·39 "),e("a",{class:"header-anchor",href:"#卷一·39","aria-label":"Permalink to “卷一·39”"},"​")],-1),e("p",null,"先子嘗言，東林講易有輕薄。子雲：每卦分六爻，作六家。使之一排居住，有時相好，有時相惡，忽然起猜疑，無端有嫉妒時，或五家讎一家，否則一處闢五處。前牽後輓，左控右訴，顛倒反覆，不知何故。竊不審聖人說易，何以設立此惡薄門戶。其言雖輕薄，隣於侮謾，然輔嗣易註與宋儒諸說易家，原是如此。且又抝曲作直，重寃疊抑，二原不猜三而就辭釋意，強坐以猜初，未嘗惡二而因文立義，誣指為惡，其意不過欲翻掀象數，造此孽境。然亦不宜惡薄如此。雖曰作易在中古，又曰當紂與文之世，然有憂患者何必至是。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
